"""Writes the TrueType font that tests/suite/graphics_fonts_pixels.bb loads into tests/suite/images.

The font has 1000 units to the em, an ascent of 800 and a descent of 200. The letter A is a solid block from 100 to 600 units
across and 0 to 800 units up and is 700 units wide, the space is 500 units wide and has nothing drawn. Every other character
is missing from the font. Because the shapes are known, a test knows exactly which pixels are drawn at any size.

Usage: generate_font_fixture.py <output file>
Needs fontTools.
"""
import sys

from fontTools.fontBuilder import FontBuilder
from fontTools.pens.ttGlyphPen import TTGlyphPen

fb = FontBuilder(1000, isTTF=True)
fb.setupGlyphOrder([".notdef", "space", "A"])
fb.setupCharacterMap({32: "space", 65: "A"})

block = TTGlyphPen(None)
block.moveTo((100, 0))
block.lineTo((100, 800))
block.lineTo((600, 800))
block.lineTo((600, 0))
block.closePath()
empty = TTGlyphPen(None).glyph()
fb.setupGlyf({".notdef": empty, "space": empty, "A": block.glyph()})
fb.setupHorizontalMetrics({".notdef": (500, 0), "space": (500, 0), "A": (700, 100)})
fb.setupHorizontalHeader(ascent=800, descent=-200)
fb.setupNameTable({"familyName": "Fixture", "styleName": "Regular"})
fb.setupOS2(sTypoAscender=800, sTypoDescender=-200, usWinAscent=800, usWinDescent=200)
fb.setupPost()
fb.save(sys.argv[1])
